pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

// This test checks the invariant: after supplyTokenTo(amount, to) completes,
// imBalances(to) increases by the credits issued. The mutant credits msg.sender
// instead, so the property is violated whenever caller != to and creditsIssued>0.

contract InvMutTest is Test {
    C c;

    // Deploy using the exact required form
    function setUp() public { c = new C(0); }

    // fuzzed inputs: caller (as address) and beneficiary 'to', and an arbitrary positive
    // mAssetAmount (we fuzz uint256). We must ensure caller != to and amount != 0 to
    // expose the mutant difference when creditsIssued>0. We keep wide domain.
    function testFuzz_property(address caller, address to, uint256 mAssetAmount) public {
        // keep addresses non-zero and distinct to witness the bug
        vm.assume(caller != address(0));
        vm.assume(to != address(0));
        vm.assume(caller != to);
        // require a positive amount
        vm.assume(mAssetAmount != 0);

        // We cannot interact with real ERC20 here; however the reference vs mutant difference
        // is purely about which mapping key is incremented (to vs msg.sender). Both contracts
        // will execute without needing actual token transfers in this test harness because
        // we only observe the public mapping via its getter. We will simulate the call context
        // by using vm.prank to set msg.sender = caller and invoke supplyTokenTo.
        // The constructor set up used a zero address savings placeholder; the function may still
        // execute path that updates imBalances mapping in the provided mutated target harness,
        // so we call and then read imBalances(to).

        vm.prank(caller);
        // call; wrap in try/catch in case the underlying contract reverts for some inputs
        bool ok;
        try c.supplyTokenTo(mAssetAmount, to) {
            ok = true;
        } catch {
            ok = false;
        }

        // The general rule we assert: after a successful supplyTokenTo call, imBalances(to)
        // as observed from the contract should be >= 0 and, importantly for this test,
        // when the call succeeded the reference increments imBalances(to) whereas the mutant
        // fails to when caller != to; thus the single assertion checks that either the call
        // reverted (ok==false) or imBalances(to) > 0. This will always hold on the reference
        // (given nonzero amount that issues credits) but fail on the mutant for some inputs.
        // We must produce exactly one assertTrue reading c's public surface.

        // Observe the mapping through its public getter imBalances(address) -> uint256
        uint256 balTo = c.imBalances(to);

        // Single assertion: if the call succeeded, imBalances(to) must be > 0.
        // This is the universal property: for all admissible inputs where call succeeds,
        // reference increases beneficiary balance; mutant will fail when it credits caller.
        assertTrue(!ok || balTo > 0);
    }
}

